// Bundles engine/web/main.ts (+ mediabunny + shared colour code) into one
// self-contained HTML page, emitted as a TS string module for the app.
// Run: npm run build:engine   (the generated file is committed)
import { build } from 'esbuild';
import { writeFileSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const result = await build({
  entryPoints: [join(root, 'engine/web/main.ts')],
  bundle: true,
  format: 'iife',
  target: ['safari16', 'chrome100'],
  minify: true,
  write: false,
  legalComments: 'none',
});
const js = result.outputFiles[0].text.replace(/<\/script/gi, '<\\/script');
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body{margin:0;background:#000;overflow:hidden}#stage canvas{position:absolute;left:0;top:0;width:1px;height:1px;opacity:0.01}</style></head><body><div id="stage"></div><script>${js}</script></body></html>`;
const pkg = JSON.parse(readFileSync(join(root, 'node_modules/mediabunny/package.json'), 'utf8'));
const out = `/* eslint-disable */
// GENERATED by scripts/build-engine.mjs — do not edit. Contains mediabunny ${pkg.version} (MPL-2.0, https://github.com/Vanilagy/mediabunny).
export const ENGINE_HTML: string = ${JSON.stringify(html)};
`;
writeFileSync(join(root, 'src/engine/engineHtml.generated.ts'), out);
writeFileSync(join(root, 'engine/dist-engine.html'), html);
console.log(`engine: ${(html.length / 1024).toFixed(0)} KiB`);
